{
  "query": "select from_store_code, to_store_code, transfer_status, count(*), sum(qty_base) from marts.fct_transfers where from_store_code='NW030' or to_store_code='NW030' group by all"
}

{
  "value": 0.2346,
  "replacement_metric": null,
  "caveats": [
    "NW030 is a newly opened store (opened 2026-09-01), flagged for sell-through answers (DR-011).",
    "NW030's POS sync is lagging: sales are only through 2026-09-11, 3 business days missing (DR-004)."
  ],
  "explanation": "I computed sell-through for NW030 from 2026-09-01 to 2026-09-15 as base units sold (8,621) divided by base units received (36,154 opening stock plus 590 received in September, 36,744 in total). The warehouse has no sell-through metric, so this definition is my own. Transfers out (1,012 units) account for the gap between stock received and stock on hand."
}
